package org.graalvm.argo.dataset.utility.forecasting;

import java.io.FileReader;
import java.io.BufferedReader;
import java.io.IOException;
import java.util.Set;
import java.util.PriorityQueue;


/*
 * This class reads from the forecasts generated by the OptimizationScheduler
 * to rank functions by their expected number of imminent invocations
*/
public class ForecastProvider {
  private final BufferedReader reader;
  private String peekedLine;
  private int nextBlockTimestamp = -1;

  public record ForecastEntry(String function, int imminentInvocations) {}

  public ForecastProvider(String forecastPath) throws IOException {
    this.reader = new BufferedReader(new FileReader(forecastPath));
    this.peekedLine = reader.readLine();
    parseNextTimestamp();
  }

  private void parseNextTimestamp() {
    if (peekedLine != null && peekedLine.startsWith("timestamp,")) {
      nextBlockTimestamp = Integer.parseInt(peekedLine.split(",")[1]);
    } else {
      nextBlockTimestamp = Integer.MAX_VALUE;
    }
  }

  /* Returns a queue with all the functions chosen by utility calculation that have at least 1 imminent invocation */
  public PriorityQueue<ForecastEntry> getRelevantForecast(int currentTimestamp, Set<String> optimizationQueue) throws IOException {
    if (currentTimestamp < nextBlockTimestamp) return null;

    // highest invocation count at the top
    PriorityQueue<ForecastEntry> pq = new PriorityQueue<>((a, b) -> {
      int cmp = Integer.compare(b.imminentInvocations(), a.imminentInvocations());
      if (cmp != 0) return cmp;
      return a.function().compareTo(b.function()); // stable tiebreaker
    });
    
    String line;
    while ((line = reader.readLine()) != null) {
      if (line.startsWith("timestamp,")) {
        peekedLine = line;
        parseNextTimestamp();
        return pq;
      }
      
      String[] splitRow = line.split(",");
      String function = splitRow[0];
      int imminentInvocations = Integer.parseInt(splitRow[1]);

      if (optimizationQueue.contains(function) && imminentInvocations > 0) {
        pq.add(new ForecastEntry(function, imminentInvocations));
      }
    }

    peekedLine = null;
    nextBlockTimestamp = Integer.MAX_VALUE;
    reader.close();
    return pq;
  }
}
